def _clean(intervals):
    out = []
    for iv in intervals:
        s, e = int(iv[0]), int(iv[1])
        if s < e:
            out.append((s, e))
    return sorted(out)


def merge(intervals):
    ivs = _clean(intervals)
    result = []
    for s, e in ivs:
        if result and s <= result[-1][1]:
            if e > result[-1][1]:
                result[-1] = (result[-1][0], e)
        else:
            result.append((s, e))
    return result


def free_gaps(intervals, window):
    ws, we = int(window[0]), int(window[1])
    if ws >= we:
        return []
    ivs = [(max(s, ws), min(e, we)) for s, e in merge(intervals)]
    ivs = [(s, e) for s, e in ivs if s < e]
    gaps = []
    cur = ws
    for s, e in ivs:
        if s > cur:
            gaps.append((cur, s))
        cur = max(cur, e)
        if cur >= we:
            return gaps
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    pts = []
    for s, e in _clean(intervals):
        pts.append((s, 1))
        pts.append((e, -1))
    pts.sort()
    # At same point, ends (-1) must be processed before starts (1)
    # since intervals are half-open: (1,3) and (3,5) don't overlap.
    pts.sort(key=lambda p: (p[0], p[1]))
    best = 0
    cur = 0
    for _, d in pts:
        cur += d
        if cur > best:
            best = cur
    return best

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.clock = clock
        self._store = OrderedDict()  # key -> (value, expiry or None)

    def _purge(self, now=None):
        if now is None:
            now = self.clock()
        dead = [k for k, (_, exp) in self._store.items() if exp is not None and now >= exp]
        for k in dead:
            del self._store[k]
        return len(dead)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self.clock()
        if key in self._store:
            self._store.move_to_end(key)
            self._store[key] = (value, now + ttl if ttl is not None else None)
            return
        if len(self._store) >= self.capacity:
            self._purge(now)
            if len(self._store) >= self.capacity:
                self._store.popitem(last=False)
        self._store[key] = (value, now + ttl if ttl is not None else None)

    def get(self, key, default=None):
        if key not in self._store:
            return default
        value, exp = self._store[key]
        if exp is not None and self.clock() >= exp:
            del self._store[key]
            return default
        self._store.move_to_end(key)
        return value

    def __contains__(self, key):
        if key not in self._store:
            return False
        _, exp = self._store[key]
        if exp is not None and self.clock() >= exp:
            del self._store[key]
            return False
        return True

    def __len__(self):
        self._purge()
        return len(self._store)

    def keys(self):
        self._purge()
        return list(self._store.keys())

    def evict_expired(self):
        return self._purge()

